//! The generator story (plan §3.2's row for this crate: "Generated by
//! `xtask` into committed Rust (phf/trie). Also generates: docs,
//! linter tables, class-sort order, test fixtures") — the SEAM half:
//! one trait every committed derived artifact implements, the
//! artifact list the `xtask` driver walks, and the two artifacts that
//! land with this slice.
//!
//! ```text
//! rows.rs (committed source of truth, hand-audited)
//!   └─ codegen::artifacts()  — the stable artifact list
//!        ├─ RootsIndex    → crates/aeolus-data/src/roots_index.rs
//!        │   (the perfect-hash root index the read side consults)
//!        └─ RegistryDocs  → docs/REGISTRY.md
//!            (the markdown audit page `registry::generate_docs`
//!             renders, committed beside the architecture plan)
//!   └─ cargo xtask gen-tables     — (re)write the committed bytes
//!   └─ cargo xtask verify-tables  — the drift gate (exit 1 on drift)
//! ```
//!
//! The one-source-of-truth claim the crate docs make is enforced, not
//! asserted: every artifact's committed bytes are pinned equal to the
//! regeneration in `tests/codegen.rs`, so a row edit that forgets
//! `cargo xtask gen-tables` fails `cargo test` — the same drift-detects
//! story plan §8 asks of the generator ("so API drift is detectable").
//!
//! What this slice deliberately does NOT generate (each grows on the
//! same seam, none half-built here): the linter's did-you-mean tables,
//! the class-sort order and the test-fixture corpus — the read side's
//! typed miss (`registry::LookupError`) and the existing corpus pins
//! cover their jobs today; when they move onto the seam they become
//! new `GeneratedArtifact` impls, and `verify-tables` pins them with
//! the same one-line list addition.

use std::fmt::Write as _;

use crate::registry;
use crate::rows::ROWS;

/// One committed artifact the generator story derives from the rows —
/// the seam the `xtask` driver walks (and the drift tests pin).
///
/// Renderers are DETERMINISTIC functions of the committed rows: the
/// same rows render byte-identical text (pinned by the tests), so the
/// committed bytes carry no hidden state — no timestamps, no iteration
/// order beyond the registry's own.
pub trait GeneratedArtifact {
    /// The stable artifact name — the driver's list surface and the
    /// drift report's key (`roots-index`, `registry-docs`).
    fn name(&self) -> &'static str;

    /// The workspace-relative path the artifact commits to (the driver
    /// resolves it against the workspace root; `--root` overrides for
    /// tests and dry runs).
    fn path(&self) -> &'static str;

    /// Render the artifact's committed bytes. Pure: same rows, same
    /// bytes (the determinism pin lives in `tests/codegen.rs`).
    fn generate(&self) -> String;
}

/// The stable artifact list — the driver's `list` surface and the
/// drift tests' walk. New artifacts join by adding one impl and one
/// list entry; `verify-tables` pins them from then on.
pub fn artifacts() -> &'static [&'static dyn GeneratedArtifact] {
    // A const, not a static: the trait-object slice is promoted, and
    // the unit-struct impls carry no state to share.
    const LIST: &[&dyn GeneratedArtifact] = &[&RootsIndex, &RegistryDocs];
    LIST
}

// ---------------------------------------------------------------------------
// Artifact 1: the roots index (the phf/trie the plan §3.2 row names)
// ---------------------------------------------------------------------------

/// The generated roots index — the registry read side's fast path.
///
/// The rows' distinct roots (154 of them over 178 rows) become a
/// seeded-FNV open-addressed hash table: generation searches seeds
/// from 0 upward for the first whose maximum displacement stays within
/// the emitted probe bound (the lowest such seed — deterministic), and
/// emits the slot table, the entry table (root text + its row indices,
/// registry order) and the longest-prefix probe the read side walks.
///
/// The SEMANTICS do not move: the index answers WHICH root a body
/// addresses (the longest dash-aligned prefix that is a root — the
/// registry's own `body_matches_root` rule), and the per-row shape
/// contract (`ValueKind::accepts`) stays exactly where it was. The
/// pre-index linear scan is kept verbatim as the documented oracle
/// (`registry::lookup_linear`); `tests/codegen.rs` batteries the two
/// against each other over the roots, the multi-dash composites, the
/// adversarial misses and a deterministic 4000-body fuzz.
pub struct RootsIndex;

impl GeneratedArtifact for RootsIndex {
    fn name(&self) -> &'static str {
        "roots-index"
    }

    fn path(&self) -> &'static str {
        "crates/aeolus-data/src/roots_index.rs"
    }

    fn generate(&self) -> String {
        render_roots_index(&build_index())
    }
}

/// One distinct root's index entry: the root text and the row indices
/// that carry it, in registry order (the shape the generated module
/// publishes and the read side walks).
#[derive(Clone)]
struct EntrySpec {
    root: &'static str,
    rows: Vec<u16>,
}

/// The computed table the renderer emits: the seed, the slot table,
/// the entries and the probe bound the generated module hard-codes.
struct IndexSpec {
    seed: u32,
    slots: usize,
    slot_table: Vec<u16>,
    entries: Vec<EntrySpec>,
    probe_bound: usize,
}

/// The distinct roots, in registry first-occurrence order, with the
/// row indices that carry each — the index entries themselves.
fn collect_entries() -> Vec<EntrySpec> {
    let mut entries: Vec<EntrySpec> = Vec::new();
    for (index, row) in ROWS.iter().enumerate() {
        match entries.iter_mut().find(|e| e.root == row.root) {
            Some(entry) => entry.rows.push(index as u16),
            None => entries.push(EntrySpec {
                root: row.root,
                rows: vec![index as u16],
            }),
        }
    }
    entries
}

/// Seeded FNV-1a (32-bit): the index's hash — the same function the
/// generated module embeds, so generation and runtime agree by
/// construction (one source of truth for the hash too).
fn fnv1a(seed: u32, text: &str) -> u32 {
    let mut hash = 0x811c_9dc5u32 ^ seed;
    for byte in text.as_bytes() {
        hash ^= u32::from(*byte);
        hash = hash.wrapping_mul(0x0100_0193);
    }
    hash
}

/// Build the index: slot count first (three times the distinct roots,
/// rounded up to the next power of two — a third-full table keeps the
/// probe bound small), then the lowest seed whose open-addressed
/// placement keeps every displacement under the probe limit. Both
/// steps are pure functions of the rows, so the emitted constants are
/// byte-stable across runs and machines.
fn build_index() -> IndexSpec {
    // The displacement budget a seed must satisfy (a miss probe walks
    // at most this many slots before the bound ends it).
    const PROBE_LIMIT: usize = 16;
    let entries = collect_entries();
    let mut slots = entries.len() * 3;
    if slots < 64 {
        slots = 64;
    }
    // Power of two, so the generated module's mask arithmetic is exact.
    slots = slots.next_power_of_two();
    loop {
        if let Some(spec) = place(&entries, slots, PROBE_LIMIT) {
            return spec;
        }
        // The seed search failed at this width (more collisions than
        // the limit absorbs): widen and retry — still deterministic,
        // the growth is a function of the rows alone.
        slots *= 2;
    }
}

/// Try seeds from 0 upward at the given table width; the FIRST seed
/// that places every entry with a displacement under `probe_limit`
/// wins (deterministic, and the generated `PROBE_BOUND` is that
/// placement's maximum displacement plus one — the miss path's
/// worst-case walk).
fn place(entries: &[EntrySpec], slots: usize, probe_limit: usize) -> Option<IndexSpec> {
    let mask = slots - 1;
    for seed in 0u32..1_000_000 {
        let mut slot_table = vec![u16::MAX; slots];
        let mut max_displacement = 0usize;
        let mut placed = true;
        for (index, entry) in entries.iter().enumerate() {
            let start = (fnv1a(seed, entry.root) as usize) & mask;
            let mut step = 0usize;
            while step < slots {
                let slot = (start + step) & mask;
                if slot_table[slot] == u16::MAX {
                    slot_table[slot] = index as u16;
                    max_displacement = max_displacement.max(step);
                    break;
                }
                step += 1;
            }
            if step == slots {
                placed = false;
                break;
            }
        }
        if placed && max_displacement < probe_limit {
            return Some(IndexSpec {
                seed,
                slots,
                slot_table,
                entries: entries.to_vec(),
                probe_bound: max_displacement + 1,
            });
        }
    }
    None
}

/// Render the generated module's committed bytes — the table, the
/// hash/probe code and the audit docs, all from the computed spec.
/// Every layout choice here is rustfmt-stable (the drift pins compare
/// RAW bytes, so the emitted text must already be canonical), and the
/// literal code lines ride `push_str` — no format strings to escape
/// the emitted braces through.
fn render_roots_index(spec: &IndexSpec) -> String {
    let mut out = String::with_capacity(spec.slots * 16 + 4096);

    // The module header: provenance, the do-not-edit contract, the
    // semantics the read side keeps.
    for line in [
        "//! The generated roots index — the registry read side's fast",
        "//! path (plan \u{a7}3.2's generator story: the phf artifact derived",
        "//! from the committed rows, consumed by `registry::lookup` and",
        "//! `registry::lookup_detailed`).",
        "//!",
        "//! GENERATED by `cargo xtask gen-tables` from `crate::rows::ROWS` —",
        "//! DO NOT EDIT. The committed bytes are pinned equal to the",
        "//! regeneration in `tests/codegen.rs`, and `cargo xtask",
        "//! verify-tables` is the same check from the CLI side; a row edit",
        "//! that forgets the regeneration fails `cargo test` first.",
        "//!",
        "//! The semantics the read side keeps: this module answers WHICH",
        "//! root a utility body addresses — the longest dash-aligned prefix",
        "//! that is a root (the registry's own `body_matches_root` rule:",
        "//! exact, or `root` + `-`) — and hands back that root's row",
        "//! indices in registry order. The per-row shape contract",
        "//! (`ValueKind::accepts`) stays in `registry.rs`, as does the",
        "//! pre-index linear scan (`registry::lookup_linear`), kept as the",
        "//! documented differential oracle the tests and the lookup bench",
        "//! battery the index against.",
        "",
    ] {
        out.push_str(line);
        out.push('\n');
    }

    let _ = writeln!(
        out,
        "/// The hash seed the generator settled on (the lowest seed whose\n/// open-addressed placement keeps every displacement under the\n/// probe bound) — a function of the rows, byte-stable.\npub const PHF_SEED: u32 = {};",
        spec.seed
    );
    let _ = writeln!(
        out,
        "\n/// The slot count: three times the distinct roots, rounded up to\n/// the next power of two (the mask arithmetic needs it).\npub const SLOTS: usize = {};",
        spec.slots
    );
    let _ = writeln!(
        out,
        "\n/// The slot-table mask (`SLOTS - 1`).\npub const MASK: usize = {};",
        spec.slots - 1
    );
    out.push_str("\n/// The sentinel an empty slot carries.\npub const EMPTY: u16 = u16::MAX;\n");
    let _ = writeln!(
        out,
        "\n/// The worst-case probe walk (the generator's maximum displacement\n/// plus one): every indexed root is reachable within this many\n/// steps, and a miss terminates at the first empty slot it meets.\npub const PROBE_BOUND: usize = {};",
        spec.probe_bound
    );
    out.push_str(
        "\n/// One indexed root: the root text and the row indices that carry\n/// it, in registry order (the shape `registry::lookup` walks).\n#[derive(Clone, Copy, Debug)]\npub struct IndexEntry {\n    /// The root text (the longest-prefix probe's match key).\n    pub root: &'static str,\n    /// The row indices under this root, ascending — the same\n    /// order the pre-index linear scan returned.\n    pub rows: &'static [u16],\n}\n",
    );

    out.push_str("\n/// The slot table: hash slot \u{2192} entry index (`EMPTY` when the\n/// slot is free). Generated, one slot per line, byte-stable.\n#[rustfmt::skip]\npub static ROOT_SLOTS: [u16; SLOTS] = [\n");
    for &slot in &spec.slot_table {
        if slot == u16::MAX {
            out.push_str("    u16::MAX,\n");
        } else {
            let _ = writeln!(out, "    {slot},");
        }
    }
    out.push_str("];\n");

    let _ = writeln!(
        out,
        "\n/// The index entries, in registry first-occurrence order (the\n/// rows' own order — the read side's answer order does not move).\n#[rustfmt::skip]\npub static ROOT_ENTRIES: [IndexEntry; {}] = [",
        spec.entries.len()
    );
    for entry in &spec.entries {
        let rows: Vec<String> = entry.rows.iter().map(ToString::to_string).collect();
        let _ = writeln!(
            out,
            "    IndexEntry {{ root: {:?}, rows: &[{}] }},",
            entry.root,
            rows.join(", ")
        );
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// Seeded FNV-1a (32-bit) — the SAME function the generator's seed\n/// search used, embedded verbatim so runtime and generation agree\n/// by construction (the drift pins cover the constants; this is\n/// the hash itself).\npub const fn fnv1a(seed: u32, text: &str) -> u32 {\n    let mut hash = 0x811c_9dc5u32 ^ seed;\n    let bytes = text.as_bytes();\n    let mut i = 0;\n    while i < bytes.len() {\n        hash ^= bytes[i] as u32;\n        hash = hash.wrapping_mul(0x0100_0193);\n        i += 1;\n    }\n    hash\n}\n\n",
    );
    out.push_str(
        "/// The hash slot a root starts its probe at (the mask arithmetic\n/// the slot table was generated for).\npub fn slot_of(root: &str) -> usize {\n    (fnv1a(PHF_SEED, root) as usize) & MASK\n}\n\n",
    );
    out.push_str(
        "/// The longest dash-aligned prefix of `body` that is a root — the\n/// read side's winner (the registry's `body_matches_root` rule is\n/// exactly `root == body || body[root.len()] == b'-'`, which makes\n/// every matching root a dash-aligned prefix, so the FIRST hit\n/// longest-first is the longest-prefix winner). The probe walks\n/// the slot table from the hash slot and stops at the first empty\n/// slot or `PROBE_BOUND` — whichever comes first.\npub fn longest_prefix(body: &str) -> Option<&'static IndexEntry> {\n    let mut end = body.len();\n    loop {\n        if let Some(entry) = probe(&body[..end]) {\n            return Some(entry);\n        }\n        // The next shorter dash-aligned prefix: drop the last `-`\n        // and everything after it (`inset-x-2` \u{2192} `inset-x` \u{2192}\n        // `inset`). The empty prefix is never a root (the row\n        // invariants pin non-empty roots), so one miss past the\n        // last dash ends the walk.\n        end = body[..end].rfind('-')?;\n    }\n}\n\n",
    );
    out.push_str(
        "/// The slot-table probe for one candidate root text: walk from the\n/// hash slot, stop on an exact-text hit, an empty slot, or the\n/// probe bound.\nfn probe(candidate: &str) -> Option<&'static IndexEntry> {\n    let start = (fnv1a(PHF_SEED, candidate) as usize) & MASK;\n    for step in 0..PROBE_BOUND {\n        let occupant = ROOT_SLOTS[(start + step) & MASK];\n        if occupant == EMPTY {\n            return None;\n        }\n        let entry = &ROOT_ENTRIES[occupant as usize];\n        if entry.root == candidate {\n            return Some(entry);\n        }\n    }\n    None\n}\n",
    );
    out
}

// ---------------------------------------------------------------------------
// Artifact 2: the registry docs page
// ---------------------------------------------------------------------------

/// The committed markdown audit page (`docs/REGISTRY.md`) — the
/// renderer is the registry's own [`registry::generate_docs`] (one
/// source of truth for the rendering too); the artifact adds the
/// committed path, the driver's write/verify surface and the drift
/// pin that keeps the page honest.
pub struct RegistryDocs;

impl GeneratedArtifact for RegistryDocs {
    fn name(&self) -> &'static str {
        "registry-docs"
    }

    fn path(&self) -> &'static str {
        "docs/REGISTRY.md"
    }

    fn generate(&self) -> String {
        registry::generate_docs()
    }
}
